import React, { Component } from 'react';

import { callPlayer, getSDK, randomString } from '../utils.js';

const SDK_URL = 'https://connect.facebook.net/en_US/sdk.js';
const SDK_GLOBAL = 'FB';
const SDK_GLOBAL_READY = 'fbAsyncInit';
const MATCH_URL = /^https?:\/\/(www\.)?facebook\.com.*\/(video(s)?|watch|story)(\.php?|\/).+$/;
const PLAYER_ID_PREFIX = 'facebook-player-';
const DEFAULT_EMBED_WIDTH = 560;
const EMBED_ASPECT_RATIO = 9 / 16;
const EMBED_READY_TIMEOUT_MS = 5000;

let facebookSdkInitialized = false;

function getContainerWidth(element: HTMLElement): number {
  if (element.offsetWidth > 0) {
    return element.offsetWidth;
  }

  const videoContainer = element.closest('[data-hook="video-player"]');
  if (videoContainer instanceof HTMLElement && videoContainer.offsetWidth > 0) {
    return videoContainer.offsetWidth;
  }

  let parent = element.parentElement;
  while (parent) {
    if (parent.offsetWidth > 0) {
      return parent.offsetWidth;
    }
    parent = parent.parentElement;
  }

  return DEFAULT_EMBED_WIDTH;
}

function getEmbedDimensions(element: HTMLElement): { width: number; height: number } {
  const width = getContainerWidth(element);
  return {
    width,
    height: Math.round(width * EMBED_ASPECT_RATIO),
  };
}

function applyEmbedDimensions(element: HTMLElement) {
  const { width, height } = getEmbedDimensions(element);
  element.setAttribute('data-width', String(width));
  element.setAttribute('data-height', String(height));
}

export class Facebook extends Component<$TSFixMe> {
  static displayName = 'Facebook';

  static canPlay = (url: string) => MATCH_URL.test(url);

  static loopOnEnded = true;

  callPlayer = callPlayer;

  playerID = this.props.config.facebook.playerId || `${PLAYER_ID_PREFIX}${randomString()}`;

  player: $TSFixMe;

  container: HTMLDivElement | null = null;

  private eventsSubscribed = false;

  private readyNotified = false;

  private embedObserver: MutationObserver | null = null;

  private embedReadyTimeout: ReturnType<typeof setTimeout> | null = null;

  componentWillUnmount() {
    this.embedObserver?.disconnect();
    if (this.embedReadyTimeout) {
      clearTimeout(this.embedReadyTimeout);
    }
  }

  private notifyEmbedReady(element: HTMLElement) {
    const iframe = element.querySelector('iframe');
    if (!iframe) {
      return;
    }

    // For some reason Facebook have added `visibility: hidden`
    // to the iframe when autoplay fails, so here we set it back.
    iframe.style.visibility = 'visible';

    if (this.readyNotified) {
      return;
    }

    this.readyNotified = true;
    this.props.onReady();
  }

  private observeEmbedRender(element: HTMLElement) {
    this.embedObserver?.disconnect();
    if (this.embedReadyTimeout) {
      clearTimeout(this.embedReadyTimeout);
    }

    if (element.querySelector('iframe')) {
      this.notifyEmbedReady(element);
      return;
    }

    this.embedObserver = new MutationObserver(() => {
      if (element.querySelector('iframe')) {
        this.embedObserver?.disconnect();
        if (this.embedReadyTimeout) {
          clearTimeout(this.embedReadyTimeout);
        }
        this.notifyEmbedReady(element);
      }
    });

    this.embedObserver.observe(element, { childList: true, subtree: true });

    this.embedReadyTimeout = setTimeout(() => {
      this.embedObserver?.disconnect();
      if (this.readyNotified) {
        return;
      }

      this.readyNotified = true;
      this.props.onReady();
    }, EMBED_READY_TIMEOUT_MS);
  }

  private setupFacebookEvents(element: HTMLElement) {
    if (this.eventsSubscribed) {
      return;
    }

    this.eventsSubscribed = true;

    const FB = window[SDK_GLOBAL as $TSFixMe] as $TSFixMe;

    FB.Event.subscribe('xfbml.render', () => {
      // Here we know the SDK has loaded, even if onReady/onPlay
      // is not called due to a video that cannot be embedded
      this.props.onLoaded();
      this.notifyEmbedReady(element);
    });

    FB.Event.subscribe('xfbml.ready', (msg: $TSFixMe) => {
      if (msg.type === 'video' && msg.id === this.playerID) {
        this.player = msg.instance;
        this.player.subscribe('startedPlaying', this.props.onPlay);
        this.player.subscribe('paused', this.props.onPause);
        this.player.subscribe('finishedPlaying', this.props.onEnded);
        this.player.subscribe('startedBuffering', this.props.onBuffer);
        this.player.subscribe('finishedBuffering', this.props.onBufferEnd);
        this.player.subscribe('error', this.props.onError);
        if (!this.props.muted) {
          // Player is muted by default
          this.callPlayer('unmute');
        }
        this.notifyEmbedReady(element);
      }
    });
  }

  private parseEmbed(element: HTMLElement) {
    applyEmbedDimensions(element);

    return getSDK(SDK_URL, SDK_GLOBAL, SDK_GLOBAL_READY as $TSFixMe).then((FB: $TSFixMe) => {
      if (!facebookSdkInitialized) {
        FB.init({
          appId: this.props.config.facebook.appId,
          xfbml: true,
          version: this.props.config.facebook.version,
        });
        facebookSdkInitialized = true;
      }

      this.setupFacebookEvents(element);
      FB.XFBML.parse(element);
      this.observeEmbedRender(element);
    });
  }

  load(_url: string, _isReady: $TSFixMe) {
    const element = this.container ?? document.getElementById(this.playerID);
    if (!element) {
      return;
    }

    this.readyNotified = false;

    const startLoad = () => {
      this.parseEmbed(element);
    };

    // Wait for layout when the player mounts inside the aspect-ratio box.
    if (element.offsetWidth === 0) {
      requestAnimationFrame(() => {
        requestAnimationFrame(startLoad);
      });
      return;
    }

    startLoad();
  }

  play() {
    if (!this.player) {
      return;
    }
    this.callPlayer('play');
  }

  pause() {
    if (!this.player) {
      return;
    }
    this.callPlayer('pause');
  }

  stop() {
    // Nothing to do
  }

  seekTo(seconds: number) {
    if (!this.player) {
      return;
    }
    this.callPlayer('seek', seconds);
  }

  setVolume(fraction: number) {
    if (!this.player) {
      return;
    }
    this.callPlayer('setVolume', fraction);
  }

  mute = () => {
    if (!this.player) {
      return;
    }
    this.callPlayer('mute');
  };

  unmute = () => {
    if (!this.player) {
      return;
    }
    this.callPlayer('unmute');
  };

  getDuration() {
    if (!this.player) {
      return null;
    }
    return this.callPlayer('getDuration');
  }

  getCurrentTime() {
    if (!this.player) {
      return null;
    }
    return this.callPlayer('getCurrentPosition');
  }

  getSecondsLoaded() {
    return null;
  }

  render() {
    const style = {
      width: '100%',
      height: '100%',
    };
    return (
      <div
        ref={element => {
          this.container = element;
        }}
        style={style}
        id={this.playerID}
        className="fb-video"
        data-href={this.props.url}
        data-autoplay={this.props.playing ? 'true' : 'false'}
        data-allowfullscreen="true"
        data-controls={this.props.controls ? 'true' : 'false'}
      />
    );
  }
}
