import React, { Component } from 'react';

import { callPlayer, getSDK } from '../utils.js';

const SDK_URL = 'https://w.soundcloud.com/player/api.js';
const SDK_GLOBAL = 'SC';
const MATCH_URL = /(?:soundcloud\.com|snd\.sc)\/[^.]+$/;

export class SoundCloud extends Component<$TSFixMe> {
  static displayName = 'SoundCloud';

  static canPlay = (url: string) => MATCH_URL.test(url);

  static loopOnEnded = true;

  callPlayer = callPlayer;

  duration: $TSFixMe = null;

  currentTime: $TSFixMe = null;

  fractionLoaded: $TSFixMe = null;

  player: $TSFixMe;

  iframe: $TSFixMe;

  load(url: $TSFixMe, isReady: $TSFixMe) {
    getSDK(SDK_URL, SDK_GLOBAL).then((SC: $TSFixMe) => {
      if (!this.iframe) {
        return;
      }
      const { PLAY, PLAY_PROGRESS, PAUSE, FINISH, ERROR } = SC.Widget.Events;
      if (!isReady) {
        this.player = SC.Widget(this.iframe);
        this.player.bind(PLAY, this.props.onPlay);
        this.player.bind(PAUSE, this.props.onPause);
        this.player.bind(PLAY_PROGRESS, (e: $TSFixMe) => {
          this.currentTime = e.currentPosition / 1000;
          this.fractionLoaded = e.loadedProgress;
        });
        this.player.bind(FINISH, () => this.props.onEnded());
        this.player.bind(ERROR, (e: $TSFixMe) => this.props.onError(e));
      }
      this.player.load(url, {
        ...this.props.config.soundcloud.options,
        callback: () => {
          this.player.getDuration((duration: $TSFixMe) => {
            this.duration = duration / 1000;
            this.props.onReady();
          });
        },
      });
    });
  }

  play() {
    this.callPlayer('play');
  }

  pause() {
    this.callPlayer('pause');
  }

  stop() {
    // Nothing to do
  }

  seekTo(seconds: $TSFixMe) {
    this.callPlayer('seekTo', seconds * 1000);
  }

  setVolume(fraction: $TSFixMe) {
    this.callPlayer('setVolume', fraction * 100);
  }

  mute = () => {
    this.setVolume(0);
  };

  unmute = () => {
    if (this.props.volume !== null) {
      this.setVolume(this.props.volume);
    }
  };

  getDuration() {
    return this.duration;
  }

  getCurrentTime() {
    return this.currentTime;
  }

  getSecondsLoaded() {
    return this.fractionLoaded * this.duration;
  }

  ref = (iframe: $TSFixMe) => {
    this.iframe = iframe;
  };

  render() {
    const { display } = this.props;
    const style = {
      width: '100%',
      height: '100%',
      display,
    };
    return (
      // oxlint-disable-next-line jsx-a11y/iframe-has-title
      <iframe
        ref={this.ref}
        src={`https://w.soundcloud.com/player/?url=${encodeURIComponent(this.props.url)}`}
        style={style}
        frameBorder={0}
        allow="autoplay"
      />
    );
  }
}
