import classNames from 'classnames';
import React, { useContext, useRef } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ImageData, PluginContainerData } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { activateCaption } from './../../_shared/figure/activate-caption.js';
import { AddCaptionButton } from './../../_shared/figure/add-caption-button.js';
import { isOnlyNodeSelected } from './../../_shared/is-only-node-selected.js';
import type { PmImageNode } from './../../_shared/pm-node-types.js';

import generalStyles from '../../editor-common/statics/styles/general-scss.js';
import generalRTLIgnoredStyles from '../../wix-rich-content-common/statics/styles/general-scss.js';
import classes from './figure-scss.js';

const stylesWithRTL = { ...generalStyles, ...generalRTLIgnoredStyles };

export const Figure: React.FC<PluginProps> = ({ NodeViewContent, ...props }) => {
  const { isMobile } = useContext(RicosContext);
  const { editor, node } = props;
  const containerRef = useRef<HTMLDivElement>(null);

  const pmNode = node.toJSON();
  const mainChild = pmNode.content[0] as PmImageNode;
  if (!mainChild) {
    return null;
  }
  const width = getContainerWidth(mainChild.attrs, isMobile);

  const isMediaSelected = isOnlyNodeSelected(editor.state, mainChild.attrs.id);
  const captionNode = pmNode.content[1]; // Caption is the second child
  const captionHasContent = !!captionNode?.content?.length;
  const captionIsVisible = !!captionNode?.attrs?.showEmpty || captionHasContent;

  // Show button when figure is selected, caption is empty, and caption is not currently visible
  const shouldShowAddCaptionButton = isMediaSelected && !captionHasContent && !captionIsVisible;

  const handleAddCaption = () => {
    const captionNode = pmNode.content[1];

    if (captionNode && captionNode.attrs?.id) {
      activateCaption(editor.view, captionNode.attrs.id);
    }
  };

  return (
    <div
      ref={containerRef}
      style={
        {
          '--ricos-internal-figure-width': width ? `${width}px` : 'auto',
          position: shouldShowAddCaptionButton ? 'relative' : undefined,
        } as React.CSSProperties
      }
      data-hook={`figure-${mainChild.type}`}
      className={getContainerClasses(mainChild.attrs.containerData)}
    >
      <NodeViewContent
        as="figure"
        className={classNames(classes.figure, {
          [classes.figureWithCaption]: shouldShowAddCaptionButton,
        })}
      />
      {shouldShowAddCaptionButton && (
        <AddCaptionButton onAddCaption={handleAddCaption} containerRef={containerRef} />
      )}
    </div>
  );
};

const getContainerWidth = (
  nodeData: { image?: ImageData['image'] | null; containerData?: PluginContainerData | null },
  isMobile: boolean
) => {
  const disableCustomWidthMapper =
    nodeData?.image?.width &&
    isMobile &&
    (Number(nodeData?.containerData?.width?.custom) || 0) > 150;

  const disableCustomWidth = disableCustomWidthMapper ?? false;

  const customWidth = !disableCustomWidth ? nodeData?.containerData?.width?.custom : undefined;
  const originalWidth =
    nodeData?.containerData?.width?.size === 'ORIGINAL' || disableCustomWidth
      ? nodeData?.image?.width
      : undefined;
  const width = customWidth || originalWidth;
  return width;
};

const upperFirst = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

const getContainerClasses = (containerData?: PluginContainerData | null) => {
  const alignment = containerData?.alignment;
  const alignmentClassName = alignment
    ? stylesWithRTL[`align${upperFirst(alignment.toLowerCase())}`]
    : undefined;

  const size = containerData?.width?.size;
  const sizeClassName =
    size && size !== 'FULL_WIDTH'
      ? stylesWithRTL[`size${upperFirst(size.toLowerCase())}`]
      : undefined;

  const textWrap = containerData?.textWrap;
  const textWrapClassName = textWrap ? undefined : stylesWithRTL.textWrapNowrap;

  return classNames(alignmentClassName, sizeClassName, textWrapClassName, classes.figureContainer);
};
