import React, { useEffect, useRef, useState } from 'react';

import type { VideoData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { isCustomUpload } from './../../_shared/is-custom-upload.js';
import { isDefined, isSSR } from './../../wix-rich-content-common/index.js';

import type { ReactPlayerWrapperProps } from '../react-player-wrapper.js';
import { ReactPlayerWrapper } from '../react-player-wrapper.js';
import styles from '../statics/styles/video-viewer-scss.js';
import type { VideoPluginEditorConfig } from '../types.js';

type Props = {
  config: VideoPluginEditorConfig;
  componentData: VideoData;
  nodeId: string;
  isLight: boolean;
  onReady?: ReactPlayerWrapperProps['onReady'];
  isLoaded?: boolean;
  seoMode?: boolean;
  jsdomMode?: boolean;
  muted?: boolean;
  onDuration?: (duration: number) => void;
  disabled?: boolean;
  onUpdateProcessing?: (processing: boolean) => void;
};

type UrlState =
  | {
      type: 'INITIAL' | 'LOADING';
      loadedUrl: undefined;
    }
  | {
      type: 'ERROR';
      error: string;
      retryCount: number;
      loadedUrl: string;
    }
  | {
      type: 'PROCESSING';
      retryCount: number;
      loadedUrl: string;
    }
  | {
      type: 'READY';
      loadedUrl: string;
    };

type State = {
  videoUrl: UrlState;
  thumbnailUrl: UrlState;
};

export const Video: React.FC<Props> = ({
  config,
  componentData,
  nodeId,
  isLight,
  onReady,
  isLoaded,
  seoMode,
  jsdomMode,
  muted,
  onDuration,
  disabled,
  onUpdateProcessing,
}) => {
  const retryTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const [playerKey, setPlayerKey] = useState('');

  const [state, setState] = useState<State>(() => {
    const { src } = componentData.video || {};

    const getInitialVideoUrlState = (): UrlState => {
      if (src?.url) {
        const normalizedUrl = normalizeVideoUrl(src.url);
        return normalizedUrl
          ? { type: 'READY', loadedUrl: normalizedUrl }
          : { type: 'INITIAL', loadedUrl: undefined };
      }
      if (src?.id && config.getVideoUrl) {
        try {
          const url = config.getVideoUrl({ pathname: src.id });
          if (typeof url === 'string') {
            const normalizedUrl = normalizeVideoUrl(url);
            return normalizedUrl
              ? { type: 'READY', loadedUrl: normalizedUrl }
              : { type: 'INITIAL', loadedUrl: undefined };
          }
        } catch {}
      }
      return { type: 'INITIAL', loadedUrl: undefined };
    };

    const getInitialThumbnailUrlState = (): UrlState => {
      const thumbnailSrc = componentData?.thumbnail?.src?.url;
      return thumbnailSrc
        ? { type: 'READY', loadedUrl: thumbnailSrc }
        : { type: 'INITIAL', loadedUrl: undefined };
    };

    return {
      videoUrl: getInitialVideoUrlState(),
      thumbnailUrl: getInitialThumbnailUrlState(),
    };
  });

  useEffect(() => {
    return () => {
      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
      }
    };
  }, []);

  useEffect(() => {
    setPlayerKey('mounted'); //remounts reactPlayer after ssr. Fixes bug where internal player id changes in client
  }, []);

  const scheduleNextRetry = (currentAttempt: number, _videoUrl: string) => {
    const maxRetries = 20;
    const nextAttempt = currentAttempt + 1;

    if (nextAttempt > maxRetries) {
      setState(prev => {
        if (prev.videoUrl.type === 'PROCESSING') {
          onUpdateProcessing?.(false);
          return {
            ...prev,
            videoUrl: {
              type: 'ERROR',
              error: 'Max retries exceeded',
              retryCount: nextAttempt,
              loadedUrl: prev.videoUrl.loadedUrl,
            },
          };
        }
        return prev;
      });
      return;
    }

    setState(prev => {
      if (prev.videoUrl.type === 'PROCESSING') {
        return {
          ...prev,
          videoUrl: {
            ...prev.videoUrl,
            retryCount: nextAttempt,
          },
        };
      }
      return prev;
    });

    const delay = Math.min(1000 * Math.pow(2, nextAttempt - 1), 30000);

    retryTimeoutRef.current = setTimeout(() => {
      // Change the key to force player remount & refetch the video
      setPlayerKey(`retry-${nextAttempt}-${Date.now()}`);
    }, delay);
  };

  const retryVideoUrl = () => {
    setState(prevState => {
      // Don't retry if already processing, or if we don't have a loaded URL
      if (
        prevState.videoUrl.type === 'PROCESSING' ||
        prevState.videoUrl.type === 'INITIAL' ||
        prevState.videoUrl.type === 'LOADING'
      ) {
        return prevState;
      }

      const loadedUrl = prevState.videoUrl.loadedUrl!;

      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
        retryTimeoutRef.current = null;
      }

      onUpdateProcessing?.(true);
      scheduleNextRetry(0, loadedUrl);

      return {
        ...prevState,
        videoUrl: {
          type: 'PROCESSING' as const,
          retryCount: 1,
          loadedUrl,
        },
      };
    });
  };

  useEffect(() => {
    const { src } = componentData.video || {};

    // Prevent loading when already in loading or processing state
    if (state.videoUrl.type === 'LOADING' || state.videoUrl.type === 'PROCESSING') {
      return;
    }

    if (src?.url) {
      const normalizedUrl = normalizeVideoUrl(src.url);
      const currentUrl = state.videoUrl.loadedUrl;
      if (normalizedUrl && normalizedUrl !== currentUrl) {
        setState(prev => ({
          ...prev,
          videoUrl: { type: 'READY', loadedUrl: normalizedUrl },
        }));
      }
      return;
    }

    if (src?.id && config.getVideoUrl) {
      const loadVideo = async () => {
        if (!src.id) {
          return;
        }

        setState(prev => ({
          ...prev,
          videoUrl: { type: 'LOADING', loadedUrl: undefined },
        }));

        try {
          const url = await config.getVideoUrl!({ pathname: src.id });
          if (url) {
            const normalizedUrl = normalizeVideoUrl(url);
            if (normalizedUrl) {
              setState(prev => {
                if (prev.videoUrl.type === 'LOADING') {
                  return {
                    ...prev,
                    videoUrl: { type: 'READY', loadedUrl: normalizedUrl },
                  };
                }
                return prev;
              });
              return;
            }
          }
        } catch {
          retryVideoUrl();
        }
      };

      loadVideo();
    }
  }, [componentData.video?.src, config.getVideoUrl]);

  useEffect(() => {
    const { src } = componentData.thumbnail || {};
    const thumbnailId = src?.id;
    const thumbnailSrc = src?.url;
    const currentThumbnailUrl = state.thumbnailUrl.loadedUrl;

    if (thumbnailSrc && thumbnailSrc !== currentThumbnailUrl) {
      setState(prev => ({
        ...prev,
        thumbnailUrl: { type: 'READY', loadedUrl: thumbnailSrc },
      }));
      return;
    }
    // @ts-ignore TODO: (plugins-no-any) remove getThumbnailUrl when we make sure it's not used anymore
    if (thumbnailId && config.getThumbnailUrl && !currentThumbnailUrl) {
      const loadThumbnail = async () => {
        setState(prev => ({
          ...prev,
          thumbnailUrl: { type: 'LOADING', loadedUrl: undefined },
        }));

        try {
          // @ts-ignore TODO: (plugins-no-any) remove getThumbnailUrl when we make sure it's not used anymore
          const url = await config.getThumbnailUrl!({ pathname: thumbnailId });
          if (url) {
            setState(prev => ({
              ...prev,
              thumbnailUrl: { type: 'READY', loadedUrl: url },
            }));
          }
        } catch {
          // Thumbnail loading failed, continue without thumbnail
          setState(prev => ({
            ...prev,
            thumbnailUrl: {
              type: 'ERROR',
              error: 'Failed to load thumbnail',
              retryCount: 0,
              loadedUrl: '',
            },
          }));
        }
      };

      loadThumbnail();
    }
    // @ts-ignore TODO: (plugins-no-any) remove getThumbnailUrl when we make sure it's not used anymore
  }, [componentData.thumbnail?.src, config.getThumbnailUrl]);

  const onReactPlayerReady: ReactPlayerWrapperProps['onReady'] = player => {
    setState(prev => {
      if (prev.videoUrl.type === 'PROCESSING') {
        onUpdateProcessing?.(false);
        if (retryTimeoutRef.current) {
          clearTimeout(retryTimeoutRef.current);
          retryTimeoutRef.current = null;
        }
        return {
          ...prev,
          videoUrl: {
            type: 'READY',
            loadedUrl: prev.videoUrl.loadedUrl,
          },
        };
      }

      if (prev.videoUrl.type === 'ERROR') {
        onUpdateProcessing?.(false);
        if (retryTimeoutRef.current) {
          clearTimeout(retryTimeoutRef.current);
          retryTimeoutRef.current = null;
        }
        return {
          ...prev,
          videoUrl: {
            type: 'READY',
            loadedUrl: prev.videoUrl.loadedUrl,
          },
        };
      }

      const currentVideoUrl = prev.videoUrl.loadedUrl;
      if (!currentVideoUrl) {
        return prev;
      }

      return {
        ...prev,
        videoUrl: {
          type: 'READY',
          loadedUrl: currentVideoUrl,
        },
      };
    });

    if (onReady) {
      onReady(player);
      return;
    }
  };

  const onVideoError = () => {
    const { src } = componentData.video || {};
    const isCustomVideo = !!src?.id || isCustomUpload(src?.url);

    if (!isCustomVideo || !src?.id) {
      return;
    }

    if (state.videoUrl.type === 'READY') {
      return retryVideoUrl();
    }

    if (state.videoUrl.type === 'PROCESSING') {
      if (retryTimeoutRef.current) {
        clearTimeout(retryTimeoutRef.current);
        retryTimeoutRef.current = null;
      }

      return scheduleNextRetry(state.videoUrl.retryCount, state.videoUrl.loadedUrl);
    }
  };

  const handleContextMenu = (e: React.MouseEvent) =>
    componentData.disableDownload && e.preventDefault();

  const getDownloadProps = () => {
    if (
      (isDefined(componentData?.disableDownload) && componentData.disableDownload) ||
      (isDefined(config?.disableDownloadDefault) && config.disableDownloadDefault)
    ) {
      return {
        config: {
          file: {
            attributes: {
              controlsList: 'nodownload',
            },
          },
        },
      };
    }

    return {
      config: {},
    };
  };

  const getLightProps = () => {
    if (!isLight) {
      return {
        isLight: false,
      } as const;
    }

    return {
      isLight: true,
      thumbnail: state.thumbnailUrl.loadedUrl,
    } as const;
  };

  const videoUrl = state.videoUrl.loadedUrl;
  if (!videoUrl) {
    return null;
  }

  const isCustomVideo = !!componentData.video?.src?.id;
  const shouldRenderSeoLink = (isSSR() || jsdomMode) && seoMode;
  const { autoPlay = false, playInLoop = false, showControls = true } = componentData.options || {};
  const poster = state.videoUrl.type === 'PROCESSING' ? state.thumbnailUrl.loadedUrl : undefined;

  if (shouldRenderSeoLink) {
    return (
      <a data-hook="video-ssr-viewer" href={videoUrl} target="_blank" rel="noopener noreferrer">
        {videoUrl}
      </a>
    );
  }

  return (
    <ReactPlayerWrapper
      className={styles.video_player}
      onContextMenu={handleContextMenu}
      controls={isLoaded !== false && showControls}
      url={videoUrl}
      onReady={onReactPlayerReady}
      onError={onVideoError}
      disabled={disabled}
      width="100%"
      height="100%"
      key={playerKey}
      onDuration={onDuration}
      onProgress={progress => {
        // @ts-ignore TODO: (plugins-no-any) remove onprogress when we make sure it's not used anymore
        config.onProgress?.({ ...progress, id: nodeId });
      }}
      // @ts-ignore TODO: (plugins-no-any) remove progressInterval when we make sure it's not used anymore
      progressInterval={config.progressInterval || 1000}
      muted={muted || autoPlay}
      isLoaded={
        isLoaded ||
        state.videoUrl.type === 'READY' ||
        state.videoUrl.type === 'PROCESSING' ||
        state.videoUrl.type === 'ERROR'
      }
      autoPlay={autoPlay}
      loop={playInLoop}
      isCustomVideo={isCustomVideo}
      poster={poster}
      {...getLightProps()}
      {...getDownloadProps()}
    />
  );
};

const normalizeVideoUrl = (url: string | undefined): string | undefined =>
  url ? (url.toLowerCase().indexOf('vimeo') === 0 ? 'https://' + url : url) : undefined; //vimeo player needs urls prefixed with http[s]
