import { Button, FileUpload, FormField } from '@wix/design-system';
import React, { useContext } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  useDevService,
} from './../../ricos-context/index.js';
import type { Helpers } from './../../ricos-types/index.js';
import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { useWixInstanceService } from './../../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProps } from './../../_shared/some-editor-props-context.js';
import type { UpdateService } from './../../_shared/upload/update-service.js';
import type { IUploadService } from './../../_shared/upload/upload-service.js';
import { MEDIA_POPOVERS_BUTTONS_NAMES_BI } from './../../wix-rich-content-common/index.js';

import { UPLOAD_TAB_UPLOAD_BUTTON } from '../data-hooks.js';
import { handleVideoUpload } from '../handle-video-upload.js';
import type { VideoPluginEditorConfig } from '../types.js';
import { VIDEO_TYPE } from '../types.js';

const FILE_INPUT_ACCEPT = 'video/*';

type UploadVideoProps = {
  nodeId?: string;
  helpers: Helpers;
  uploadService?: IUploadService;
  updateService?: UpdateService;
  closeModal: () => void;
  logBi: LogBiFn;
} & Pick<VideoPluginEditorConfig, 'disableDownloadDefault'>;

export const UploadVideo: React.FC<UploadVideoProps> = ({
  nodeId,
  helpers,
  uploadService,
  closeModal,
  disableDownloadDefault,
  logBi,
}) => {
  const { t } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const wixInstance = useWixInstanceService();
  const { metaSiteId } = wixInstance();
  const editorProps = useEditorProps();
  const modalService = useContext(ModalServiceContext);
  const devService = useDevService();

  const handleUploadClick = async () => {
    helpers?.onPluginsPopOverClick?.({
      pluginId: VIDEO_TYPE,
      buttonName: MEDIA_POPOVERS_BUTTONS_NAMES_BI.upload,
    });

    logBi({ dataHook: UPLOAD_TAB_UPLOAD_BUTTON });

    handleVideoUpload({
      services: {
        uploadService: uploadService!,
        devService,
        wixInstance,
        editorProps,
        modals: modalService,
      },
      config: { disableDownloadDefault },
      publicCommands: getPublicCommands(),
      nodeId,
    });

    closeModal();
  };

  return (
    <FormField label={t('VideoCustomUploadModal_Title')} maxLines={2}>
      {metaSiteId ||
      devService().handleFileSelection ||
      devService().handleFileUpload ||
      editorProps.pickMedia ? (
        <FileUpload onChange={() => {}} accept={FILE_INPUT_ACCEPT}>
          {() => (
            <Button
              dataHook={UPLOAD_TAB_UPLOAD_BUTTON}
              onClick={handleUploadClick}
              fullWidth
              size="small"
            >
              {t('VideoUploadModal_CustomVideoClickText')}
            </Button>
          )}
        </FileUpload>
      ) : null}
    </FormField>
  );
};
