export const getHighestQualityVideo = (
  videos: { format: string; quality: string; url: string }[]
) => {
  const mp4 = videos.filter(video => video.format === 'mp4');
  const getVideoQuality = (video: { quality: string }) => parseInt(video.quality, 10);
  return mp4.reduce((result, video) =>
    getVideoQuality(video) > getVideoQuality(result) ? video : result
  );
};
