import { useContext, useEffect, useState } from 'react';

import { EditorContext } from './../../ricos-context/index.js';
import type { PublicCommands } from './../../ricos-types/index.js';
import type { Editor } from './../../tiptap/core/index.js';

export const useEditorSelection = (editor: Editor) => {
  const { getPublicCommands } = useContext(EditorContext);

  const [selection, setSelection] = useState<ReturnType<PublicCommands['getSelection']>>(() =>
    getPublicCommands().getSelection()
  );

  useEffect(() => {
    const onSelectionUpdate = () => {
      setSelection(getPublicCommands().getSelection());
    };

    editor.on('selectionUpdate', onSelectionUpdate);

    return () => {
      editor.off('selectionUpdate', onSelectionUpdate);
    };
  }, []);

  return selection;
};
