import React, { Component } from 'react';

import { callPlayer, getSDK, randomString } from '../utils.js';

const SDK_URL = 'https://player.twitch.tv/js/embed/v1.js';
const SDK_GLOBAL = 'Twitch';
const MATCH_VIDEO_URL = /(?:www\.|go\.)?twitch\.tv\/videos\/(\d+)($|\?)/;
const MATCH_CHANNEL_URL = /(?:www\.|go\.)?twitch\.tv\/([a-z0-9_]+)($|\?)/;
const PLAYER_ID_PREFIX = 'twitch-player-';

export class Twitch extends Component<$TSFixMe> {
  static displayName = 'Twitch';

  static canPlay = (url: string) => MATCH_VIDEO_URL.test(url) || MATCH_CHANNEL_URL.test(url);

  static loopOnEnded = true;

  player: $TSFixMe;

  callPlayer = callPlayer;

  playerID = this.props.config.twitch.playerId || `${PLAYER_ID_PREFIX}${randomString()}`;

  load(url: string, isReady: string) {
    const { playsinline, onError, config, controls } = this.props;
    const isChannel = MATCH_CHANNEL_URL.test(url);
    // @ts-expect-error
    const id = isChannel ? url.match(MATCH_CHANNEL_URL)[1] : url.match(MATCH_VIDEO_URL)[1];
    if (isReady) {
      if (isChannel) {
        this.player.setChannel(id);
      } else {
        this.player.setVideo('v' + id);
      }
      return;
    }
    getSDK(SDK_URL, SDK_GLOBAL).then((Twitch: $TSFixMe) => {
      this.player = new Twitch.Player(this.playerID, {
        video: isChannel ? '' : id,
        channel: isChannel ? id : '',
        height: '100%',
        width: '100%',
        playsinline,
        autoplay: this.props.playing,
        muted: this.props.muted,
        // https://github.com/CookPete/react-player/issues/733#issuecomment-549085859
        controls: isChannel ? true : controls,
        ...config.twitch.options,
      });
      const { READY, PLAYING, PAUSE, ENDED, ONLINE, OFFLINE } = Twitch.Player;
      this.player.addEventListener(READY, this.props.onReady);
      this.player.addEventListener(PLAYING, this.props.onPlay);
      this.player.addEventListener(PAUSE, this.props.onPause);
      this.player.addEventListener(ENDED, this.props.onEnded);

      // Prevent weird isLoading behaviour when streams are offline
      this.player.addEventListener(ONLINE, this.props.onLoaded);
      this.player.addEventListener(OFFLINE, this.props.onLoaded);
    }, onError);
  }

  play() {
    this.callPlayer('play');
  }

  pause() {
    this.callPlayer('pause');
  }

  stop() {
    this.callPlayer('pause');
  }

  seekTo(seconds: $TSFixMe) {
    this.callPlayer('seek', seconds);
  }

  setVolume(fraction: $TSFixMe) {
    this.callPlayer('setVolume', fraction);
  }

  mute = () => {
    this.callPlayer('setMuted', true);
  };

  unmute = () => {
    this.callPlayer('setMuted', false);
  };

  getDuration() {
    return this.callPlayer('getDuration');
  }

  getCurrentTime() {
    return this.callPlayer('getCurrentTime');
  }

  getSecondsLoaded() {
    return null;
  }

  render() {
    const style = {
      width: '100%',
      height: '100%',
    };
    // @ts-expect-error
    return <div style={style} id={this.playerID} loading="lazy" />;
  }
}
